# Compatibility shim: the project used to be a package (pyaot/checker.py,
# pyaot/codegen.py, ...). Allow `from pyaot.checker import check_source` style
# imports against this single file by registering aliases in sys.modules.
def _register_submodule_aliases() -> None:
    mod = sys.modules[__name__]
    if not hasattr(mod, "__path__"):
        mod.__path__ = []  # mark as package so 'pyaot.x' imports resolve
    for sub in ("types", "subtype", "annotations", "diagnostics",
                "codegen", "checker", "cli"):
        sys.modules.setdefault(f"{__name__}.{sub}", mod)


_register_submodule_aliases()


if __name__ == "__main__":
    sys.exit(main())
